<script setup lang="ts">
import {reactive,ref,onMounted,computed} from 'vue';
import {useI18n} from 'vue-i18n';
import {useRouter} from 'vue-router';
import {useDashboard} from '../stores/dashboard';
import {personalRequest} from '../api/dashboard';
import HealthConnection from '../components/HealthConnection.vue';
import type {OnboardingInput} from '../health-types';
const goalOptions=[{value:'track',label:'goalTrack'},{value:'maintain',label:'goalMaintain'},{value:'lose',label:'goalLose'},{value:'gain',label:'goalGain'}] as const;
const activityOptions=[{value:'low',label:'activityLow'},{value:'moderate',label:'activityModerate'},{value:'high',label:'activityHigh'}] as const;
const healthOptions=[{value:'health_connect',label:'healthAndroid'},{value:'healthkit',label:'healthApple'},{value:'wear_os',label:'healthWear'},{value:'unsupported',label:'healthUnsupported'},{value:'later',label:'healthLater'}] as const;
const {t}=useI18n();const store=useDashboard();const router=useRouter();const step=ref(0);const busy=ref(false);const failed=ref(false);
const form=reactive<OnboardingInput>({goal_kind:'track',height_cm:null,baseline_kg:null,target_kg:null,activity_level:'moderate',health_preference:'later',consent:false});
const needsReadings=computed(()=>['health_connect','healthkit','wear_os'].includes(form.health_preference)&&!(store.data?.health?.status==='available'&&store.data.health.daily?.provider===form.health_preference));
onMounted(async()=>{const token=store.token;try{const saved=await personalRequest<Partial<OnboardingInput>>('onboarding',token);if(store.token!==token)return;for(const key of ['goal_kind','height_cm','baseline_kg','target_kg','activity_level','health_preference'] as const){if(saved[key]!=null)Object.assign(form,{[key]:saved[key]});}}catch{failed.value=true;}});
async function submit(){if(step.value<2){step.value++;return;}busy.value=true;failed.value=false;const token=store.token;try{await personalRequest('onboarding',token,{...form,height_cm:Number(form.height_cm),baseline_kg:Number(form.baseline_kg),target_kg:form.target_kg?Number(form.target_kg):null},'PUT');if(token!==store.token)return;await store.refresh();await router.push('/');}catch{failed.value=true;}finally{busy.value=false;}}
</script>
<template><section class="widget onboarding"><span class="eyebrow">KINDEE · {{step+1}} / 3</span><h2>{{t('onboardTitle')}}</h2><p>{{t('onboardIntro')}}</p><ol class="setup-steps"><li v-for="(key,i) in ['stepGoal','stepState','stepHealth']" :aria-current="i===step?'step':undefined">{{t(key)}}</li></ol><form @submit.prevent="submit"><fieldset v-if="step===0"><legend>{{t('stepGoal')}}</legend><label v-for="option in goalOptions" :key="option.value" class="choice"><input v-model="form.goal_kind" type="radio" :value="option.value">{{t(option.label)}}</label></fieldset><fieldset v-if="step===1"><legend>{{t('stepState')}}</legend><label>{{t('heightCm')}}<input v-model.number="form.height_cm" type="number" min="100" max="250" step="0.1" required></label><label>{{t('baselineKg')}}<input v-model.number="form.baseline_kg" type="number" min="20" max="400" step="0.01" required></label><label>{{t('targetKg')}}<input v-model.number="form.target_kg" type="number" min="20" max="400" step="0.01"></label><label>{{t('activityLevel')}}<select v-model="form.activity_level"><option v-for="option in activityOptions" :key="option.value" :value="option.value">{{t(option.label)}}</option></select></label></fieldset><fieldset v-if="step===2"><legend>{{t('stepHealth')}}</legend><label>{{t('healthPreference')}}<select v-model="form.health_preference"><option v-for="option in healthOptions" :key="option.value" :value="option.value">{{t(option.label)}}</option></select></label><p>{{t('healthUpstream')}}</p><p v-if="form.health_preference==='later'||form.health_preference==='unsupported'">{{t('healthNoData')}}</p><p v-if="needsReadings" role="status">{{t('healthLinkRequired')}}</p><label class="check-label"><input v-model="form.consent" type="checkbox" required>{{t('consentProfile')}}</label></fieldset><div class="setup-actions"><button v-if="step>0" type="button" @click="step--">{{t('previousStep')}}</button><button :disabled="busy||step===2&&(!form.consent||needsReadings)">{{t(step===2?'finishOnboarding':'nextStep')}}</button></div></form><p v-if="failed" class="error" role="alert">{{t('requestFailed')}}</p><p class="widget-note">{{t('onboardingHelp')}}</p></section><HealthConnection v-if="step===2&&form.health_preference!=='later'&&form.health_preference!=='unsupported'"/></template>
